# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student


def make(last, first, section, email="x@school.test"):
    return Student("1", last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_sorted_by_name_and_aligned(self):
        rows = contact_rows([
            make("Thistle", "Bram", "A", "bram@sch.test"),
            make("Ash", "Cy", "B10", "cy@school.test"),
        ])
        self.assertEqual(rows, [
            "Ash, Cy        B10  cy@school.test",
            "Thistle, Bram  A    bram@sch.test",
        ])

    def test_accepts_any_iterable(self):
        rows = contact_rows(iter([make("Ash", "Cy", "A")]))
        self.assertEqual(len(rows), 1)

    def test_missing_email_names_student(self):
        students = [
            make("Ash", "Cy", "A"),
            make("Roe", "Di", "A", None),
        ]
        with self.assertRaises(ProjectError) as caught:
            contact_rows(students)
        self.assertIn("Roe, Di", str(caught.exception))

    def test_blank_email_is_missing(self):
        with self.assertRaises(ProjectError):
            contact_rows([make("Roe", "Di", "A", "")])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
